INSERT INTO quay_logs (id, port_call_id, had_deviation, description, r_punctuality, r_cooperation, r_equipment, boat_note, delivered_by, delivered_at) VALUES
  ('ql_00001', 'pc_00001', 0, NULL, 4, 4, 4, 'Effektiv lossing. Kranen litt treg i starten.', 'u_per', '2026-10-16T05:04:00.000Z'),
  ('ql_00002', 'pc_00002', 0, NULL, 5, 5, 5, 'Presis og ryddig. Mannskapet hjalp med surring.', 'u_ola', '2026-10-04T10:40:00.000Z'),
  ('ql_00003', 'pc_00003', 1, 'Ankom 07:30, 1,5 t etter ETA. Fire mann ventet uten oppgaver.', 2, 4, 4, 'Ring skipper kvelden før for oppdatert ETA.', 'u_jonas', '2026-09-29T09:15:00.000Z'),
  ('ql_00004', 'pc_00004', 0, NULL, 5, 5, 5, 'Kom før tiden, alt klart til lossing.', 'u_per', '2026-09-25T08:52:00.000Z'),
  ('ql_00005', 'pc_00005', 0, NULL, 4, 4, 4, 'Litt venting på papirer, ellers greit.', 'u_jonas', '2026-09-20T13:20:00.000Z'),
  ('ql_00006', 'pc_00006', 0, NULL, 4, 4, 4, 'Godt samarbeid. Egen kran i god stand.', 'u_ola', '2026-09-13T16:30:00.000Z'),
  ('ql_00007', 'pc_00007', 1, 'Båtkrana stoppet to ganger under lossing. Ca. 2 t forsinkelse. Brukte egne stropper.', 2, 3, 1, 'Ha egne stropper klare neste gang.', 'u_ola', '2026-09-05T12:45:00.000Z'),
  ('ql_00008', 'pc_00008', 0, NULL, 4, 4, 4, 'Greit anløp.', 'u_jonas', '2026-08-31T11:05:00.000Z'),
  ('ql_00009', 'pc_00009', 1, 'Mannskap uten hjelm på kaia. 3 paller skadet ved lasting fra båtkran.', 2, 1, 2, 'Krev verneutstyr før lasting starter.', 'u_jonas', '2026-08-23T14:10:00.000Z'),
  ('ql_00010', 'pc_00010', 0, NULL, 3, 3, 3, 'Smal luke, tok 1 t ekstra.', 'u_per', '2026-08-17T10:25:00.000Z'),
