INSERT INTO messages (id, port_call_id, author_id, kind, body, created_at) VALUES
  ('m_00001', 'pc_00001', 'u_jonas', 'user', 'Fjordvik er losset og har gått. Kaibok levert.', '2026-10-16T04:58:00.000Z'),
  ('m_00002', 'pc_00001', NULL, 'system', 'Kaibok levert av Per H. · ingen avvik · 4,0 av 5. Anløpet er satt til Ferdig.', '2026-10-16T05:04:00.000Z'),
  ('m_00003', 'pc_a1', 'u_jonas', 'user', 'Alle 180 paller står klar i sone B på kai 2 – Hav salt på Europall, Sukker salt 1:2 på SRS-pall.', '2026-10-16T05:12:00.000Z'),
  ('m_00004', 'pc_a1', 'u_ola', 'user', 'Kran sjekket og klar. Starter lasting når de har fortøyd.', '2026-10-16T05:20:00.000Z'),
  ('m_00005', 'pc_a1', 'u_kari', 'user', '@Jonas B. kunden spør om vi rekker avgang 11:00 – ser det greit ut?', '2026-10-16T05:41:00.000Z'),
  ('m_00006', 'pc_a1', 'u_jonas', 'user', 'Ja, god margin.', '2026-10-16T05:44:00.000Z'),
  ('m_00007', 'pc_a2', 'u_henrik', 'user', 'Agenten melder ETA 09:15, ca. 20 min senere enn plan. @Jonas B. rekker dere å starte lossing før lunsj?', '2026-10-16T05:58:00.000Z'),
  ('m_00008', 'pc_a2', 'u_jonas', 'user', 'Ja. @Ola N. tar trucken fra kai 2 når Havbris er lastet.', '2026-10-16T06:04:00.000Z'),
  ('m_00009', 'pc_a2', 'u_ola', 'user', 'Ok. Obs: båtkrana hadde trøbbel sist – vi legger egne stropper klare.', '2026-10-16T06:06:00.000Z'),
  ('m_00010', 'pc_a3', 'u_mari', 'user', '@Kari S. Polarstrand kolliderer med Kystlast på kai 1. Kan kunden flytte til 13:00?', '2026-10-16T05:40:00.000Z'),
  ('m_00011', 'pc_a3', 'u_kari', 'user', 'Spør agenten nå. Svar innen 09:00.', '2026-10-16T05:52:00.000Z'),
  ('m_00012', 'pc_a4', 'u_henrik', 'user', 'Tollpapirer for Nitrite-pallene er sendt agenten.', '2026-10-16T05:30:00.000Z');
